import Foundation

extension Bundle {
    // SwiftPM 6.2 looks beside Bundle.main rather than in Contents/Resources.
    // Resolve the packaged location first so a moved app never depends on the
    // absolute build-directory fallback generated by SwiftPM.
    static var notProtonResources: Bundle {
        if let url = Bundle.main.resourceURL?
            .appending(path: "NotProtonApp_NotProtonApp.bundle"),
           let bundle = Bundle(url: url) {
            return bundle
        }
        return .module
    }
}
